    float attenuation = rangeCutoff / max(att.x + att.y * dist + att.z * distSq, 0.0001);
    float downward = clamp((uLightPosition[i].y - worldPos.y) / max(dist, 1.0), 0.0, 1.0);
    float spread = mix(1.05, 0.5 + 0.75 * downward * downward, isCeilingFixture);
    total += diff * (attenuation * spread);
  }
  return mix(min(total, vec3(2.5)), max(total, vec3(1.35)), clamp(emissive, 0.0, 1.0));
}

void main(void) {
  float isDoor = step(0.5, abs(vSurface.x - (vWorld.x + vWorld.y)));
  float isFloor = step(vHeight, -0.15) * (1.0 - isDoor);
  if (vHeight < -0.21)
    discard;
  if (isDoor > 0.5)
    if (vHeight < -0.01)
      discard;
  if (uHasFog == 1 && vDepth >= uFogFar) {
    gl_FragColor = vec4(uFogColor, 0.5);
    return;
  }
  vec3 steel = texture2D(uSampler, vTextureCoord).rgb;
  vec3 color = steel;
  float lit = smoothstep(0.06, 0.2, max(steel.b, steel.g) - steel.r);
  float amount = 0.0;
  if (lit < 0.95) {
    vec2 p = mix(vSurface, vWorld, isFloor);
    float scale = mix(mix(38.0, 26.0, isDoor), 44.0, isFloor);
    float spots = noise(p / scale + 21.0) * 0.6 + noise(p / (scale * 0.41) + 9.0) * 0.4;
    if (spots > 0.48) {
      float drift = (noise(p / 360.0 + 90.0) - 0.5) * isFloor;
      float thresh = mix(mix(0.68, 0.58, isDoor), 0.63, isFloor);
      float area = smoothstep(thresh, thresh + 0.11, spots - drift * 0.1);
      vec2 seam = abs(fract(p / 32.0) - 0.5);
      float nearSeam = 1.0 - smoothstep(0.34, 0.5, max(seam.x, seam.y));
      float band = (1.0 - isFloor) * (1.0 - smoothstep(0.0, 7.0, min(abs(vSurface.y - 8.0), abs(vSurface.y - 54.0))));
      area = clamp(area + (nearSeam * 0.28 + band * 0.35) * smoothstep(thresh - 0.08, thresh + 0.02, spots), 0.0, 1.0);
      float near = 1.0 - smoothstep(220.0, 620.0, vDepth);
      amount = area * 0.8;
      if (near > 0.01 && area > 0.25) {
        vec2 texel = floor(p);
        float grain = noise(texel / 3.0) * 0.6 + noise(texel / 1.3 + 40.0) * 0.4;
        amount = area * mix(0.8, 0.3 + grain * 0.9, near);
